pages/account/orders/details:
{{#partial "head"}}
    <link rel="preload" href="{{cdn 'assets/dist/theme-bundle.chunk.account.js' resourceHint='preload' as='script'}}" as="script">
{{/partial}}

{{#partial "page"}}
{{inject 'selectItem' (lang 'forms.validate.account.reorder.select_item')}}

<div class="account">
    {{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}
    <h1 class="page-heading">{{lang 'account.orders.heading' }}</h1>
    {{> components/account/navigation account_page='orders'}}
    <h2 class="page-heading title">{{lang 'account.orders.details.heading' number=order.id}}</h2>
    <div class="account-body">

        {{#each order.status_messages}}
            {{> components/common/alert/alert-info message}}
        {{/each}}
        <div class="account-content">
            {{> components/account/order-contents order=order}}

            <div class="eyeva__account-order-footer">
                <div class="eyeva__account-order-actions">
                    <form class="account-reorder-form" action="{{order.reorder_url}}" method="post" data-account-reorder-form>
                        <input type="hidden" name="orderid" value="{{order.id}}">
                        {{#each order.items}}
                            {{#if show_reorder}}
                                <input type="hidden" name="reorderitem[{{order_product_id}}]">
                            {{/if}}
                        {{/each}}
                        <input type="submit" class="button button--small button--outline" value="{{lang 'account.orders.details.reorder'}}">
                    </form>
                    {{#if settings.returns_enabled}}
                        {{#if order.is_complete}}
                            <a href="{{order.return_url}}" class="button button--small button--outline">{{lang 'account.orders.details.return'}}</a>
                        {{/if}}
                    {{/if}}
                </div>

                <dl class="account-orderTotal">
                    {{#each order.total_rows}}
                        {{#if value.value}}
                            <dt class="account-orderTotal-key">{{label}}:</dt>
                            <dd class="account-orderTotal-value">{{value.formatted}}</dd>
                        {{/if}}
                    {{/each}}
                </dl>
            </div>
        </div>

        <aside class="account-sidebar">
            <section class="account-sidebar-block">
                <h3 class="account-sidebar-heading">
                    {{lang 'account.orders.details.order_details'}}
                    <button data-print-invoice="{{order.invoice_url}}" class="button button--small button--primary">{{lang 'account.orders.details.print_invoice'}}</button>
                </h3>
                <dl class="definitionList">
                    <dt class="definitionList-key">{{lang 'account.orders.details.order_status'}}</dt>
                    <dd class="definitionList-value">{{order.status_text}}</dd>
                    <dt class="definitionList-key">{{lang 'account.orders.details.payment_date'}}</dt>
                    <dd class="definitionList-value">{{order.date}}</dd>
                    <dt class="definitionList-key">{{lang 'account.orders.details.order_total'}}</dt>
                    <dd class="definitionList-value">{{order.total.formatted}}</dd>
                    {{#if order.payment_method}}
                        <dt class="definitionList-key">{{lang 'account.orders.details.payment_method'}}</dt>
                        <dd class="definitionList-value">
                            {{order.payment_method}}
                            {{#if order.card_number_last_four}}
                                {{lang 'account.orders.details.card_ending' card=order.card_number_last_four}}
                            {{/if}}
                        </dd>
                    {{/if}}
                    {{#if order.order_instructions}}
                        <dt class="order-payments-description">{{lang 'account.orders.details.how_to_pay'}}</dt>
                        <dd class="order-payments-value order-payments-value--long">{{nl2br order.order_instructions}}</dd>
                    {{/if}}
                </dl>

                {{#if order.comments}}
                    <h3 class="account-sidebar-heading">{{lang 'account.orders.details.comments'}}</h3>
                    <div class="_comments">{{order.comments}}</div>
                {{/if}}

                <h3 class="account-sidebar-heading">{{lang 'account.orders.details.bill_to'}}</h3>
                <ul class="account-order-address">
                    <li><span class="_name">{{{ sanitize order.billing_address.full_name}}}</span> <span class="_phone">{{{sanitize order.billing_address.phone}}}</span></li>
                    <li>{{{ sanitize order.billing_address.company}}}</li>
                    <li>
                        {{{ sanitize order.billing_address.address_lines.[0]}}},
                        {{{ sanitize order.billing_address.address_lines.[1]}}},
                        {{{ sanitize order.billing_address.city}}},
                        {{{ sanitize order.billing_address.state}}}
                        {{{ sanitize order.billing_address.zip}}},
                        {{{ sanitize order.billing_address.country}}}
                    </li>
                </ul>
            </section>

            {{#or order.shipping_address shipments}}
                <section class="account-sidebar-block">
                    {{#if shipments}}
                        <h3 class="account-sidebar-heading">{{lang 'account.orders.details.shipments.header'}}</h3>
                        {{#each shipments}}
                            <dl class="definitionList">
                                <dt class="definitionList-key">{{lang 'account.orders.details.shipments.date'}}:</dt>
                                <dd class="definitionList-value">{{date_shipped}}</dd>
                                <dt class="definitionList-key">{{lang 'account.orders.details.shipments.method'}}:</dt>
                                <dd class="definitionList-value">{{shipping_provider}}</dd>
                                <dt class="definitionList-key">{{lang 'account.orders.details.shipments.link'}}:</dt>
                                <dd class="definitionList-value">
                                    {{#if shipping_track.url}}
                                        <a href="{{shipping_track.url}}">
                                    {{/if}}

                                    {{#if show_shipping_method}}
                                        {{shipping_track.number}} &mdash; {{shipping_method}}
                                    {{else}}
                                        {{shipping_track.number}}
                                    {{/if}}

                                    {{#if shipping_track.url}}
                                        </a>
                                    {{/if}}
                                </dd>
                            </dl>
                        {{/each}}
                    {{/if}}
                    {{#if order.shipping_address}}
                        <h3 class="account-sidebar-heading">{{lang 'account.orders.details.ship_to'}}</h3>
                        <ul class="account-order-address">
                            <li><span class="_name">{{{ sanitize order.shipping_address.full_name}}}</span> <span class="_phone">{{{sanitize order.shipping_address.phone}}}</span></li>
                            <li>{{{ sanitize order.shipping_address.company}}}</li>
                            <li>
                                {{{ sanitize order.shipping_address.address_lines.[0]}}},
                                {{{ sanitize order.shipping_address.address_lines.[1]}}},
                                {{{ sanitize order.shipping_address.city}}},
                                {{{ sanitize order.shipping_address.state}}}
                                {{{ sanitize order.shipping_address.zip}}},
                                {{{ sanitize order.shipping_address.country}}}
                            </li>
                            {{#if order.has_multiple_shipping_addresses}}
                                <li class="_multi">
                                    {{lang 'account.orders.details.ship_to_multi_text'}}
                                </li>
                            {{/if}}
                        </ul>
                    {{/if}}
                </section>
            {{/or}}

            {{#if order.pickup_address}}
                <section class="account-sidebar-block">
                    <h3 class="account-sidebar-heading">{{lang 'account.orders.details.pickup'}}</h3>
                    {{#each order.pickup_address}}
                        <dl class="definitionList">
                            <dt class="definitionList-key">{{lang 'account.orders.details.pickup_method'}}</dt>
                            <dd class="definitionList-value">{{sanitize pickup_method_display_name}}</dd>
                        </dl>

                        <ul class="account-order-address">
                            <li><span class="_name">{{{ sanitize location_name}}}</span></li>
                            <li>
                                {{{ sanitize location_line_1}}},
                                {{{ sanitize location_line_2}}},
                                {{{ sanitize location_city}}},
                                {{{ sanitize location_state}}}
                                {{{ sanitize location_zip}}},
                                {{{ sanitize location_country_name}}}
                            </li>
                        </ul>

                        <dl class="definitionList">
                            {{#if location_phone}}
                            <dt class="definitionList-key">{{lang 'account.orders.details.phone'}}</dt>
                            <dd class="definitionList-value">{{{ sanitize location_phone}}}</dd>
                            {{/if}}
                            {{#if order.pickup_address.location_email}}
                            <dt class="definitionList-key">{{lang 'account.orders.details.email'}}</dt>
                            <dd class="definitionList-value">{{{ sanitize location_email}}}</dd>
                            {{/if}}
                        </dl>

                        <ul class="account-order-address">
                            <li><b>{{{ lang 'account.orders.details.opening_hours'}}}</b></li>
                            <li>{{{ sanitize collection_time_description}}}</li>
                        </ul>
                    {{/each}}
                </section>
            {{/if}}

        </aside>

    </div>
</div>
{{/partial}}
{{> layout/base}}

components/common/footer:
{{#if banners.bottom}}
    <div class="banners" data-banner-location="bottom">
        {{#each banners.bottom_metadata}}
            <div class="banner" data-event-type="promotion" data-entity-id="{{this.id}}" data-name="{{this.banner-name}}" data-position="{{this.location}}" data-name="{{this.banner-name}}">
                <div data-event-type="promotion-click">
                    {{{this.content}}}
                </div>
            </div>
        {{/each}}
    </div>
{{/if}}
{{#if settings.show_newsletter_box}}
    <section class="eyeva__newsletter">
        <div class="container">
            {{> components/common/subscription-form}}
        </div>
    </section>
{{/if}}
<footer class="footer" role="contentinfo">
    <h2 class="footer-title-sr-only">{{lang 'footer.title'}}</h2>
    <div class="footer-main">
        <div class="container">
            <section class="footer-info">
                <article class="footer-info-col" data-section-type="footer-categories">
                    <h3 class="footer-info-heading">{{lang 'footer.categories'}}</h3>
                    <ul class="footer-info-list">
                        {{#each categories}}
                            <li>
                                <a href="{{url}}">{{name}}</a>
                            </li>
                        {{/each}}
                    </ul>
                    {{{region name="footer_info_col_1--global"}}}
                </article>

                <article class="footer-info-col" data-section-type="footer-webPages">
                    <h3 class="footer-info-heading">{{lang 'footer.navigate'}}</h3>
                    <ul class="footer-info-list">
                        {{#each pages}}
                            <li>
                                <a href="{{url}}">{{name}}</a>
                            </li>
                        {{/each}}
                        {{#if settings.gift_certificates_enabled}}
                            <li>
                                <a href="{{urls.gift_certificate.purchase}}">{{lang 'common.gift_cert'}}</a>
                            </li>
                        {{/if}}
                        <li>
                            <a href="{{urls.sitemap}}">{{lang 'sitemap.page_title'}}</a>
                        </li>
                    </ul>
                    {{{region name="footer_info_col_2--global"}}}
                </article>

                <article class="footer-info-col" data-section-type="footer-brands">
                    {{#and theme_settings.shop_by_brand_show_footer shop_by_brand.length}}
                        <h3 class="footer-info-heading">{{lang 'footer.brands'}}</h3>
                        <ul class="footer-info-list">
                            {{#each shop_by_brand}}
                                <li>
                                    <a href="{{url}}">{{name}}</a>
                                </li>
                            {{/each}}
                            <li><a href="{{urls.brands}}">{{lang 'common.view_all'}}</a></li>
                        </ul>
                    {{/and}}
                    {{{region name="footer_info_col_3--global"}}}
                </article>
                <article class="footer-info-col">
                    {{{region name="footer_info_col_4--global"}}}
                </article>
            </section>
            <section class="footer-contacts">
                <article class="footer-info-col" data-section-type="storeInfo">
                    <h3 class="footer-info-heading">{{lang 'footer.info'}}</h3>
                    {{#all settings.phone_number theme_settings.phone_text}}
                        <p>{{#replace '{phone}' theme_settings.phone_text}}{{settings.phone_number}}{{else}}{{{theme_settings.phone_text}}}{{/replace}}</p>
                    {{/all}}

                    {{{region name="footer_support--global"}}}

                    {{#if settings.phone_number}}
                        <p class="footer-contacts-callout"><a href="tel:{{settings.phone_number}}"><i class="icon" aria-hidden="true"><svg><use href="#icon-mobile-screen"></use></svg></i>{{settings.phone_number}}</a></p>
                    {{/if}}

                    {{#if theme_settings.social_icon_placement_bottom '!==' 'bottom_none'}}
                        {{> components/common/social-links}}
                    {{/if}}

                    {{#if settings.address}}
                        <address>{{settings.address}}</address>
                    {{/if}}
                </article>
                {{{region name="ssl_site_seal--global"}}}
            </section>
        </div>
    </div>

    {{> components/common/payment-icons}}

    <div class="footer-copyright">
        <div class="container">
            <p class="powered-by">
                {{#if theme_settings.show_copyright_footer}}
                    &copy; {{moment format="YYYY"}} {{settings.store_name}}.
                {{/if}}
                {{#if theme_settings.show_powered_by}}
                    {{lang 'footer.powered_by'}} <a href="https://www.bigcommerce.com?utm_source=merchant&amp;utm_medium=poweredbyBC" rel="nofollow">BigCommerce</a>.
                {{/if}}
            </p>

            {{{region name="footer_copyright_links--global"}}}
        </div>
    </div>
</footer>

components/eyeva/header/navuser-currency:
{{#or customer (unless settings.hide_price_from_guests)}}
    {{#if currency_selector.currencies.length '>' 1}}
        <button class="navUser-action _currency" type="button"
            data-collapsible="navUser-currency"
            aria-controls="navUser-currency"
            aria-expanded="false"
            aria-label="{{currency_selector.active_currency_code}}"
            data-menu-gap-cover
        >
            <span class="navUser-label-alt">{{currency_selector.active_currency_code}}</span>
            <i class="icon" aria-hidden="true"><svg><use href="#icon-chevron-down" /></svg></i>
        </button>
        <div class="navUser-subMenu" id="navUser-currency" aria-hidden="true" data-menu-dropdown {{#if theme_settings.logo-position '==' 'center'}}data-ignore-header-position{{/if}}>
            <ul class="navUser-childList">
                {{#each currency_selector.currencies}}
                    <li class="navUser-childList-item">
                        <a class="navUser-childList-action" href="{{{switch_url}}}"
                            data-currency-code="{{{code}}}"
                            {{#if cart_currency_switch_url.length '>' 0 }}
                                data-cart-currency-switch-url="{{{cart_currency_switch_url}}}"
                            {{/if}}
                            data-warning="{{lang 'common.currency_switch_promotion'}}"
                        >
                            {{#if is_active}}
                                <strong>{{code}} - {{name}}</strong>
                            {{else}}
                                {{code}} - {{name}}
                            {{/if}}
                        </a>
                    </li>
                {{/each}}
            </ul>
        </div>
    {{/if}}
{{/or}}

components/eyeva/header/navigation-child:
{{#if children}}
    {{#unless id}}
        {{#if (merge this id=(concat 'page-' (incrementVar 'incrementId')))}}{{/if}}
    {{/unless}}
    <a class="navPages-childList-action _mega {{#if is_active}} activePage{{/if}}" href="{{url}}">
        <span class="navPages-label">{{name}}</span>
    </a>
    <div class="navPages-megaMenu-subMenu">
        <ul class="navPages-megaMenu-childList">
            {{#each children}}
                <li class="navPages-childList-item">
                    {{> components/eyeva/header/navigation-child-list depth=(add ../depth 1)}}
                </li>
            {{/each}}
        </ul>
    </div>
{{else}}
    <a class="navPages-childList-action _mega {{#if is_active}} activePage{{/if}}" href="{{url}}">
        <span class="navPages-label">{{name}}</span>
    </a>
{{/if}}
